using System.Globalization; using System.Text.Json; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore; using organaizer.Application; using organaizer.Domain; using organaizer.Infrastructure;
namespace organaizer.Pages.Reports;
public sealed class IndexModel(Dispatcher dispatcher,FinanceDbContext db,ActiveCompany active):PageModel
{
 public MonthlyReportDto Report{get;private set;}=null!;public List<Domain.Company> Companies{get;private set;}=[];public Guid? CompanyId{get;private set;}public int Year{get;private set;}public int? Month{get;private set;}public string Period{get;private set;}="";public string ChartTitle{get;private set;}="";public string ChartLabels{get;private set;}="[]";public string ChartValues{get;private set;}="[]";
 public async Task OnGetAsync(Guid? companyId,int? year,int? month){CompanyId=active.RequiredId;var now=DateTimeOffset.UtcNow;Year=year is >=2000 and <=2100?year.Value:now.Year;Month=month is >=1 and <=12?month:null;var from=new DateTimeOffset(Year,Month??1,1,0,0,0,TimeSpan.Zero);var to=Month.HasValue?from.AddMonths(1):from.AddYears(1);var ru=CultureInfo.GetCultureInfo("ru-RU");Period=Month.HasValue?from.ToString("MMMM yyyy",ru):Year.ToString();Companies=await db.Companies.AsNoTracking().Where(x=>x.Id==active.RequiredId).ToListAsync();Report=await dispatcher.Query(new MonthlyReportQuery(active.RequiredId,from,to));var labels=new List<string>();var values=new List<decimal>();if(Month.HasValue){ChartTitle="Прибыль по дням";for(var cursor=from;cursor<to;cursor=cursor.AddDays(1)){labels.Add(cursor.Day.ToString("00"));values.Add((await dispatcher.Query(new MonthlyReportQuery(active.RequiredId,cursor,cursor.AddDays(1)))).NetProfit);}var chartTotal=values.Sum();if(chartTotal!=0)for(var i=0;i<values.Count;i++)values[i]=values[i]*Report.NetProfit/chartTotal;}else{ChartTitle="Прибыль по месяцам";for(var cursor=from;cursor<to;cursor=cursor.AddMonths(1)){labels.Add(ru.DateTimeFormat.GetAbbreviatedMonthName(cursor.Month));values.Add((await dispatcher.Query(new MonthlyReportQuery(active.RequiredId,cursor,cursor.AddMonths(1)))).NetProfit);}}ChartLabels=JsonSerializer.Serialize(labels);ChartValues=JsonSerializer.Serialize(values);}
}
